     1→/**
     2→ * L3 上下文层：加载进入 LLM 上下文的数据源 Schema。
     3→ * 防御链：落库 schema → scope 白名单过滤 → 敏感列过滤 → 摘要生成，结果缓存 5 分钟。
     4→ * P2-7 缓存接 StateStore：REDIS_URL 配置时多实例共享同一份缓存，
     5→ * 数据源写操作后 invalidateSchemaCache 跨实例同步失效（内存模式行为与原实现一致）。
     6→ * 同时返回数据源 status，作为数据源级"AI 问数开关"（disconnected 拒绝问数）。
     7→ */
     8→import { getPool } from '../infra/db';
     9→import { getStateStore } from '../infra/stateStore';
    10→import { applyDataScope, rowFiltersByTableName } from './scope';
    11→import { summarizeSchema } from './schemaGuidance';
    12→import { filterSensitiveColumns } from './queryGuard';
    13→import { getFilePhysicalTable, isFileDataSourceType } from './fileDataSource';
    14→import type { SchemaTable } from './schemaTypes';
    15→import type mysql from 'mysql2/promise';
    16→import { logger } from '../infra/logger';
    17→
    18→/** data_sources 表上下文加载行（SELECT 指定列） */
    19→interface DataSourceRow extends mysql.RowDataPacket {
    20→  name: string;
    21→  schema_json: string | null;
    22→  scope_json: string | null;
    23→  status: string;
    24→  type: string;
    25→  allow_introspection: number;
    26→  /** v0.9.34 文件数据源判定：config.physicalTable 存在即走应用库真实执行 */
    27→  config_json: string | null;
    28→}
    29→
    30→const SCHEMA_CACHE_PREFIX = 'sctx:';
    31→const CACHE_TTL_SEC = 5 * 60;
    32→
    33→interface CacheEntry {
    34→  schema: SchemaTable[];
    35→  guidance: string;
    36→  status: string;
    37→  /** 数据源类型（mysql 才走真实 SQL 执行；null = 前端提交 schema 的演示模式） */
    38→  dsType: string | null;
    39→  sensitiveRemoved: string[];
    40→  /** 数据源级数据自省开关（Vanna intermediate_sql 借鉴） */
    41→  allowIntrospection: boolean;
    42→  /** P1-3 行级权限：实际表名 → 行过滤谓词（执行层 AST 强制注入） */
    43→  rowFilters: Record<string, string>;
    44→  /** 数据源显示名（注入 prompt 防止 LLM 把库名当数据过滤值） */
    45→  dataSourceName: string;
    46→  /** v0.9.34 文件数据源已落应用库物理表（csv/json/excel + config.physicalTable）；旧缓存无此字段按 false 处理 */
    47→  fileBacked?: boolean;
    48→}
    49→
    50→/** 数据源配置/结构变更后调用，使缓存失效（跨实例：Redis 模式下 deleteByPrefix 广播清理） */
    51→export async function invalidateSchemaCache(dataSourceId?: string): Promise<void> {
    52→  const store = getStateStore();
    53→  if (dataSourceId) await store.deleteByPrefix(`${SCHEMA_CACHE_PREFIX}${dataSourceId}`);
    54→  else await store.deleteByPrefix(SCHEMA_CACHE_PREFIX);
    55→}
    56→
    57→export interface SchemaContext {
    58→  schema: SchemaTable[];
    59→  guidance: string;
    60→  /** null 表示数据源未落库（使用前端提交的 schema，不缓存） */
    61→  status: string | null;
    62→  /** 数据源类型；null 表示未落库（演示模式） */
    63→  dsType: string | null;
    64→  sensitiveRemoved: string[];
    65→  /** 数据自省开关；演示模式恒关 */
    66→  allowIntrospection: boolean;
    67→  /** P1-3 行级权限（实际表名 → 谓词）；演示模式恒空 */
    68→  rowFilters: Record<string, string>;
    69→  /** 数据源显示名；演示模式为空串 */
    70→  dataSourceName: string;
    71→  /** 文件数据源已落应用库物理表（问数/报表走真实执行链路）；演示模式恒 false */
    72→  fileBacked: boolean;
    73→}
    74→
    75→/**
    76→ * 支持真实执行的数据源判定（v0.9.34 统一收口）：数据库型（mysql/postgresql/greenplum）
    77→ * 或已落物理表的文件型（fileBacked）。问数/计划/报表/异步任务 7 处分流点统一使用本判定。
    78→ */
    79→export function isLiveCapableType(dsType: string | null | undefined, fileBacked?: boolean): boolean {
    80→  return dsType === 'mysql' || dsType === 'postgresql' || dsType === 'greenplum' || fileBacked === true;
    81→}
    82→
    83→function parseJson<T>(v: unknown, fallback: T): T {
    84→  if (v === null || v === undefined) return fallback;
    85→  if (typeof v === 'object') return v as T;
    86→  try {
    87→    return JSON.parse(String(v)) as T;
    88→  } catch {
    89→    return fallback;
    90→  }
    91→}
    92→
    93→function fromClientSchema(clientSchema: unknown): SchemaContext {
    94→  const filtered = filterSensitiveColumns(Array.isArray(clientSchema) ? clientSchema : []);
    95→  return {
    96→    schema: filtered.schema,
    97→    guidance: summarizeSchema(filtered.schema),
    98→    status: null,
    99→    dsType: null,
   100→    sensitiveRemoved: filtered.removed,
   101→    allowIntrospection: false,
   102→    rowFilters: {},
   103→    dataSourceName: '',
   104→    fileBacked: false,
   105→  };
   106→}
   107→
   108→export async function loadSchemaContext(dataSourceId: unknown, clientSchema: unknown): Promise<SchemaContext> {
   109→  if (typeof dataSourceId !== 'string' || !dataSourceId) {
   110→    return fromClientSchema(clientSchema);
   111→  }
   112→
   113→  const cacheKey = `${SCHEMA_CACHE_PREFIX}${dataSourceId}`;
   114→  const raw = await getStateStore().get(cacheKey);
   115→  if (raw) {
   116→    try {
   117→      const cached = JSON.parse(raw) as CacheEntry;
   118→      return {
   119→        schema: cached.schema,
   120→        guidance: cached.guidance,
   121→        status: cached.status,
   122→        dsType: cached.dsType,
   123→        sensitiveRemoved: cached.sensitiveRemoved,
   124→        allowIntrospection: cached.allowIntrospection,
   125→        rowFilters: cached.rowFilters,
   126→        dataSourceName: cached.dataSourceName || '',
   127→        fileBacked: cached.fileBacked === true,
   128→      };
   129→    } catch {
   130→      // 缓存体损坏视为未命中，走查库重建
   131→    }
   132→  }
   133→
   134→  try {
   135→    const [rows] = await getPool().query<DataSourceRow[]>(
   136→      'SELECT name, schema_json, scope_json, status, type, allow_introspection, config_json FROM data_sources WHERE id = ?',
   137→      [dataSourceId]
   138→    );
   139→    const ds = rows[0];
   140→    if (!ds) return fromClientSchema(clientSchema);
   141→
   142→    const scoped = applyDataScope(parseJson<SchemaTable[]>(ds.schema_json, []), parseJson(ds.scope_json, null));
   143→    const filtered = filterSensitiveColumns(scoped);
   144→    const entry: CacheEntry = {
   145→      schema: filtered.schema,
   146→      guidance: summarizeSchema(filtered.schema),
   147→      status: String(ds.status || 'connected'),
   148→      dsType: String(ds.type || ''),
   149→      sensitiveRemoved: filtered.removed,
   150→      allowIntrospection: Number(ds.allow_introspection) === 1,
   151→      rowFilters: rowFiltersByTableName(scoped, parseJson(ds.scope_json, null)),
   152→      dataSourceName: String(ds.name || ''),
   153→      fileBacked: isFileDataSourceType(String(ds.type || '')) && getFilePhysicalTable(parseJson(ds.config_json, {})) !== null,
   154→    };
   155→    await getStateStore().setEx(cacheKey, JSON.stringify(entry), CACHE_TTL_SEC);
   156→    return {
   157→      schema: entry.schema,
   158→      guidance: entry.guidance,
   159→      status: entry.status,
   160→      dsType: entry.dsType,
   161→      sensitiveRemoved: entry.sensitiveRemoved,
   162→      allowIntrospection: entry.allowIntrospection,
   163→      rowFilters: entry.rowFilters,
   164→      dataSourceName: entry.dataSourceName,
   165→      fileBacked: entry.fileBacked === true,
   166→    };
   167→  } catch (err) {
   168→    logger.warn('[Schema] load datasource schema failed, fallback to client schema:', err);
   169→    return fromClientSchema(clientSchema);
   170→  }
   171→}
   172→

