     5→ * INCR + 分布式锁并发槽），多实例共享且进程崩溃后槽位可自动过期释放。
     6→ */
     7→import { getStateStore, isRedisEnabled } from './stateStore';
     8→
     9→const WINDOW_MS = 60 * 60 * 1000; // 1 小时滑动窗口
    10→const maxPerWindow = () => Number(process.env.USER_QUERY_RATE_MAX) || 20;
    11→/** Redis 并发槽 TTL：覆盖最长问数链路耗时，崩溃后自动释放避免永久锁死（内存模式同样以此兜底） */
