    53→ * 内存模式同样记录 token 与过期时间：客户端断开可提前释放（见路由 res.on('close')），
    54→ * 旧链路跑完后的 finally 释放因 token 不匹配为 no-op，不会误删新请求的槽。
    55→ */
    56→export async function acquireQuerySlot(userId: number, token = 'local', now: number = Date.now()): Promise<boolean> {
    57→  if (isRedisEnabled()) {
    58→    try {
    59→      return await getStateStore().acquireLock(`uqs:${userId}`, token, SLOT_TTL_SEC);
    60→    } catch {
    61→      return false; // fail-closed
    62→    }
    63→  }
    64→  const cur = inflight.get(userId);
    65→  if (cur && cur.exp > now) return false;
    66→  inflight.set(userId, { token, exp: now + SLOT_TTL_SEC * 1000 });
    67→  return true;
    68→}
    69→
    70→export async function releaseQuerySlot(userId: number, token = 'local'): Promise<void> {
    71→  if (isRedisEnabled()) {
    72→    try {
    73→      await getStateStore().releaseLock(`uqs:${userId}`, token);
    74→    } catch {
    75→      // 释放失败由 TTL 过期兜底
    76→    }
    77→    return;
    78→  }
    79→  const cur = inflight.get(userId);
    80→  if (cur && cur.token === token) inflight.delete(userId);
    81→}
    82→
    83→// 定期清理过期窗口记录
    84→setInterval(() => {
    85→  const windowStart = Date.now() - WINDOW_MS;
    86→  for (const [key, list] of hits.entries()) {
    87→    const fresh = list.filter((t) => t > windowStart);
    88→    if (fresh.length === 0) hits.delete(key);
    89→    else hits.set(key, fresh);
    90→  }
    91→}, WINDOW_MS).unref();
    92→
    93→/** 仅供单元测试使用 */
    94→export function _resetForTest(): void {
    95→  hits.clear();
    96→  inflight.clear();
    97→}
