     1→/**
     2→ * v0.9.2 长任务队列（改进计划 2-1）：MySQL 任务表 + 内置 worker，不引入外部 MQ。
     3→ *
     4→ * 场景：报告生成（双阶段 LLM 链，分钟级）、问数报告、PDF 导出（Python 子进程）。
     5→ * 同步端点长时间占用 HTTP 连接与用户并发槽，且实例重启任务即丢失；
     6→ * 队列化后提交即返回 taskId，worker 独立并发执行，前端轮询获取结果。
     7→ *
     8→ * 隔离设计：
     9→ * - worker 并发上限 TASK_WORKER_CONCURRENCY（默认 2），与交互问数互不争抢用户并发槽；
    10→ * - 任务内 SQL 执行走分析链连接池（见 sqlExecutor 连接池分级）；
    11→ * - 每用户在途任务上限 TASK_QUEUE_USER_MAX（默认 3），防排队风暴。
    12→ *
    13→ * 崩溃恢复：RUNNING 任务心跳（默认每 5s）超时 90s 视为孤儿，
    14→ * attempts < 2 自动回 PENDING 重跑，否则标 FAILED（不静默丢任务）。
    15→ */
    16→import { randomUUID } from 'node:crypto';
    17→import type mysql from 'mysql2/promise';
    18→import { getPool } from './db';
    19→import { logger } from './logger';
    20→
    21→export type TaskType = 'report_generate' | 'report_generate_from_query' | 'report_export_pdf';
    22→export type TaskStatus = 'PENDING' | 'RUNNING' | 'SUCCESS' | 'FAILED';
    23→
    24→export interface AsyncTask {
    25→  id: string;
    26→  type: TaskType;
    27→  status: TaskStatus;
    28→  userId: number;
    29→  username: string;
    30→  progress: string;
    31→  error: string;
    32→  attempts: number;
    33→  result?: unknown;
    34→  createdAt: string;
    35→  startedAt?: string | null;
    36→  finishedAt?: string | null;
    37→}
    38→
    39→/** 任务处理器：payload 为提交时快照；reportProgress 更新进度文案并顺带心跳 */
    40→export type TaskHandler = (
    41→  payload: any,
    42→  ctx: { taskId: string; reportProgress: (text: string) => Promise<void> },
    43→) => Promise<unknown>;
    44→
    45→/** 领取查询行（async_tasks 表列投影；payload_json 为 JSON 文本） */
    46→interface ClaimedTaskRow extends mysql.RowDataPacket {
    47→  id: string;
    48→  type: TaskType;
    49→  payload_json: string | null;
    50→  attempts: number;
    51→}
    52→
    53→/** 孤儿巡检行（async_tasks 表列投影） */
    54→interface OrphanTaskRow extends mysql.RowDataPacket {
    55→  id: string;
    56→  attempts: number;
    57→}
    58→
    59→const handlers = new Map<TaskType, TaskHandler>();
    60→
    61→export function registerTaskHandler(type: TaskType, handler: TaskHandler): void {
    62→  handlers.set(type, handler);
    63→}
    64→
    65→/** 配置（环境变量可覆盖，非法值回退默认） */
    66→export function taskWorkerConcurrency(): number {
    67→  const n = Number(process.env.TASK_WORKER_CONCURRENCY);
    68→  return Number.isFinite(n) && n >= 1 ? Math.min(10, Math.floor(n)) : 2;
    69→}
    70→export function taskUserQueueMax(): number {
    71→  const n = Number(process.env.TASK_QUEUE_USER_MAX);
    72→  return Number.isFinite(n) && n >= 1 ? Math.min(50, Math.floor(n)) : 3;
    73→}
    74→export function taskHeartbeatTimeoutMs(): number {
    75→  const n = Number(process.env.TASK_HEARTBEAT_TIMEOUT_MS);
    76→  return Number.isFinite(n) && n >= 10000 ? n : 90_000;
    77→}
