    79→  const n = Number(process.env.TASK_EXEC_TIMEOUT_MS);
    80→  return Number.isFinite(n) && n >= 30_000 ? n : 10 * 60_000;
    81→}
    82→
    83→/** 孤儿任务重试上限：超过后不再回队列，标 FAILED 防无限循环 */
    84→export const TASK_MAX_ATTEMPTS = 2;
    85→
    86→/** 建表（幂等；由 initSchema 调用） */
    87→export async function ensureTaskTable(pool?: mysql.Pool): Promise<void> {
    88→  const p = pool ?? getPool();
    89→  await p.query(`
    90→    CREATE TABLE IF NOT EXISTS async_tasks (
    91→      id VARCHAR(48) PRIMARY KEY,
    92→      type VARCHAR(32) NOT NULL,
    93→      status ENUM('PENDING','RUNNING','SUCCESS','FAILED') NOT NULL DEFAULT 'PENDING',
    94→      user_id INT NOT NULL,
    95→      username VARCHAR(50) NOT NULL DEFAULT '',
    96→      payload_json MEDIUMTEXT,
    97→      result_json MEDIUMTEXT NULL,
    98→      error VARCHAR(500) NOT NULL DEFAULT '',
    99→      progress VARCHAR(100) NOT NULL DEFAULT '',
   100→      attempts INT NOT NULL DEFAULT 0,
   101→      worker_id VARCHAR(64) NOT NULL DEFAULT '',
   102→      heartbeat_at TIMESTAMP NULL DEFAULT NULL,
   103→      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
   104→      started_at TIMESTAMP NULL DEFAULT NULL,
   105→      finished_at TIMESTAMP NULL DEFAULT NULL,
   106→      INDEX idx_tasks_status (status, created_at),
   107→      INDEX idx_tasks_user (user_id, created_at),
   108→      INDEX idx_tasks_heartbeat (status, heartbeat_at)
   109→    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
   110→  `);
   111→  // 存量迁移：id 列放宽到 48（task_<uuid> 为 41 字符；MODIFY 幂等）
   112→  try {
   113→    await p.query('ALTER TABLE async_tasks MODIFY COLUMN id VARCHAR(48) NOT NULL');
   114→  } catch {
   115→    // 列已是目标宽度或表刚创建时跳过
   116→  }
   117→}
   118→
   119→/** 提交任务：同用户在途（PENDING/RUNNING）超上限时拒绝，返回 null 由路由转 429 */
   120→export async function submitTask(
   121→  type: TaskType,
   122→  payload: unknown,
   123→  user: { id: number; username: string },
