   234→      result = typeof row.result_json === 'string' ? JSON.parse(row.result_json) : row.result_json;
   235→    } catch {
   236→      result = null;
   237→    }
   238→  }
   239→  return {
   240→    id: String(row.id),
   241→    type: row.type,
   242→    status: row.status,
   243→    userId: Number(row.user_id),
   244→    username: String(row.username || ''),
   245→    progress: String(row.progress || ''),
   246→    error: String(row.error || ''),
   247→    attempts: Number(row.attempts || 0),
   248→    ...(result !== undefined ? { result } : {}),
   249→    createdAt: row.created_at instanceof Date ? row.created_at.toISOString() : String(row.created_at || ''),
   250→    startedAt: row.started_at instanceof Date ? row.started_at.toISOString() : row.started_at ? String(row.started_at) : null,
   251→    finishedAt: row.finished_at instanceof Date ? row.finished_at.toISOString() : row.finished_at ? String(row.finished_at) : null,
   252→  };
   253→}
   254→
   255→export async function getTask(taskId: string, pool?: mysql.Pool): Promise<AsyncTask | null> {
   256→  const p = pool ?? getPool();
   257→  const [rows] = await p.query<mysql.RowDataPacket[]>('SELECT * FROM async_tasks WHERE id = ?', [taskId]);
   258→  const row = rows[0];
   259→  return row ? toAsyncTask(row) : null;
   260→}
   261→
   262→export async function listUserTasks(userId: number, limit = 20, pool?: mysql.Pool): Promise<AsyncTask[]> {
   263→  const p = pool ?? getPool();
   264→  const [rows] = await p.query<mysql.RowDataPacket[]>(
   265→    'SELECT * FROM async_tasks WHERE user_id = ? ORDER BY created_at DESC LIMIT ?',
   266→    [userId, Math.min(100, Math.max(1, limit))]
   267→  );
   268→  return rows.map(toAsyncTask);
   269→}
   270→
   271→// ---------------- worker 循环 ----------------
   272→
   273→const workerId = `w_${process.pid}_${randomUUID().slice(0, 8)}`;
   274→let workerTimer: NodeJS.Timeout | null = null;
   275→let runningCount = 0;
   276→
   277→async function runOneTask(task: { id: string; type: TaskType; payload: any }): Promise<void> {
   278→  const handler = handlers.get(task.type);
   279→  if (!handler) {
   280→    await failTask(task.id, `未注册的任务类型：${task.type}`);
   281→    return;
   282→  }
   283→  const reportProgress = async (text: string) => {
   284→    await heartbeatTask(task.id, workerId, text).catch(() => undefined);
   285→  };
   286→  // 执行期心跳：长任务（分钟级 LLM 链）默认每 5s 续命，防被孤儿回收误判
   287→  const hbTimer = setInterval(() => {
   288→    void heartbeatTask(task.id, workerId).catch(() => undefined);
   289→  }, 5000);
   290→  // 执行超时兜底：超时后标失败（底层连接/子进程可能仍在，由各自超时机制收敛）
   291→  let timeoutTimer: NodeJS.Timeout | null = null;
   292→  const timeoutPromise = new Promise<never>((_, reject) => {
   293→    timeoutTimer = setTimeout(() => reject(new Error('任务执行超时')), taskExecTimeoutMs());
   294→  });
   295→  try {
   296→    const result = await Promise.race([handler(task.payload, { taskId: task.id, reportProgress }), timeoutPromise]);
   297→    await completeTask(task.id, result);
   298→    logger.info(`[TaskQueue] ${task.type} ${task.id} 完成`);
   299→  } catch (err: any) {
   300→    await failTask(task.id, err?.message || String(err));
   301→    logger.warn(`[TaskQueue] ${task.type} ${task.id} 失败:`, err?.message || err);
   302→  } finally {
   303→    clearInterval(hbTimer);
   304→    if (timeoutTimer) clearTimeout(timeoutTimer);
   305→  }
   306→}
   307→
   308→async function workerTick(): Promise<void> {
   309→  // 孤儿巡检搭车 worker 周期（低频：约每 15 tick ≈ 30s 一次）
   310→  tickCount += 1;
   311→  if (tickCount % 15 === 1) {
   312→    const recovered = await recoverOrphanTasks().catch(() => 0);
   313→    if (recovered > 0) logger.warn(`[TaskQueue] 回收孤儿任务 ${recovered} 个`);
   314→  }
   315→  while (runningCount < taskWorkerConcurrency()) {
   316→    const task = await claimNextTask(workerId);
   317→    if (!task) return;
   318→    runningCount += 1;
   319→    void runOneTask(task).finally(() => {
   320→      runningCount -= 1;
   321→    });
   322→  }
   323→}
   324→
   325→let tickCount = 0;
   326→
   327→/** 启动 worker（幂等）；先做一次孤儿回收覆盖"停机期间 RUNNING 任务" */
   328→export function startTaskWorker(intervalMs = 2000): void {
   329→  if (workerTimer) return;
   330→  void recoverOrphanTasks().then((n) => {
   331→    if (n > 0) logger.warn(`[TaskQueue] 启动回收孤儿任务 ${n} 个`);
   332→  }).catch((err) => logger.warn('[TaskQueue] 启动孤儿回收失败:', err?.message || err));
   333→  workerTimer = setInterval(() => {
   334→    void workerTick().catch((err) => logger.warn('[TaskQueue] worker tick 失败:', err?.message || err));
   335→  }, intervalMs);
   336→  workerTimer.unref?.();
   337→  logger.info(`[TaskQueue] worker 已启动（并发上限 ${taskWorkerConcurrency()}，workerId=${workerId}）`);
   338→}
   339→
   340→/** 测试/停机用 */
   341→export function stopTaskWorker(): void {
   342→  if (workerTimer) {
   343→    clearInterval(workerTimer);
   344→    workerTimer = null;
   345→  }
   346→}
   347→

