     1→/**
     2→ * 智能问数纵深防御：输入净化（L1）、上下文敏感列过滤（L3）、历史净化（L4）。
     3→ * 全部为纯函数，服务端在 LLM 调用前强制执行，不信任前端提交的任何内容。
     4→ */
     5→import type { SchemaTable } from './schemaTypes';
     6→
     7→// L1：单条提问最大长度（架构图约定 500 字，超长截断而非拒绝）
     8→export const MAX_QUESTION_LENGTH = 500;
     9→// L4：进入 LLM 上下文的历史轮数上限
    10→export const MAX_HISTORY_TURNS = 5;
    11→
    12→// 提示注入特征：命中即拒绝。清单保持保守，避免误伤正常中文业务提问。
    13→const INJECTION_PATTERNS: RegExp[] = [
    14→  /ignore\s+(all\s+)?(the\s+)?(previous|above|prior)\s+(instructions?|prompts?|rules?)/i,
    15→  /disregard\s+(all\s+)?(the\s+)?(previous|above|prior)\s+(instructions?|prompts?)/i,
    16→  /forget\s+(all\s+)?(the\s+)?(previous|above)\s+(instructions?|rules?)/i,
    17→  /忽略(你|所有|全部)?(之前|以上|上述|原先)(的)?(指令|指示|命令|提示词|规则|设定)/,
    18→  /(忘记|忘掉)(之前|以上|上述)(的)?(指令|指示|提示词|规则|设定)/,
    19→  /你现在是(一个)?(新|其他|别的|完全不同)/,
    20→  /(jailbreak|越狱模式|DAN\s*模式)/i,
    21→];
    22→
    23→// 控制字符（保留换行与制表符，其余剥离）
    24→// eslint-disable-next-line no-control-regex
    25→const CONTROL_CHARS = /[\u0000-\u0008\x0B\x0C\x0E-\x1F\x7F]/g;
    26→
    27→export function containsInjection(text: string): boolean {
    28→  return INJECTION_PATTERNS.some((p) => p.test(text));
    29→}
    30→
    31→export type SanitizeResult =
    32→  | { ok: true; question: string; truncated: boolean }
    33→  | { ok: false; reason: string };
    34→
    35→/**
    36→ * L1 输入净化：类型校验 → 控制字符过滤 → 注入特征拒绝 → 500 字截断。
    37→ */
    38→export function sanitizeQuestion(raw: unknown): SanitizeResult {
    39→  if (typeof raw !== 'string') {
    40→    return { ok: false, reason: '查询内容格式无效' };
    41→  }
    42→  const cleaned = raw.replace(CONTROL_CHARS, '').trim();
    43→  if (!cleaned) {
    44→    return { ok: false, reason: '查询内容不能为空' };
    45→  }
    46→  if (containsInjection(cleaned)) {
    47→    return { ok: false, reason: '查询内容包含不允许的指令，请仅描述数据分析需求' };
    48→  }
    49→  if (cleaned.length > MAX_QUESTION_LENGTH) {
    50→    return { ok: true, question: cleaned.slice(0, MAX_QUESTION_LENGTH), truncated: true };
    51→  }
    52→  return { ok: true, question: cleaned, truncated: false };
    53→}
    54→
    55→/**
    56→ * L4 历史净化：仅保留 user 消息（assistant 输出一律丢弃，防止模型输出回流污染上下文），
    57→ * 每条过注入检测（命中即丢弃该条），截断 500 字，最多保留最近 5 轮。
    58→ */
    59→export function sanitizeHistory(raw: unknown): { role: 'user'; content: string }[] {
    60→  if (!Array.isArray(raw)) return [];
    61→  const turns: { role: 'user'; content: string }[] = [];
    62→  for (const m of raw) {
    63→    if (!m || m.role !== 'user' || typeof m.content !== 'string') continue;
    64→    const cleaned = m.content.replace(CONTROL_CHARS, '').trim();
    65→    if (!cleaned || containsInjection(cleaned)) continue;
    66→    turns.push({ role: 'user', content: cleaned.slice(0, MAX_QUESTION_LENGTH) });
    67→  }
    68→  return turns.slice(-MAX_HISTORY_TURNS);
    69→}
    70→
    71→// L3：敏感列特征（列名或描述命中即从 AI 上下文剔除；文件数据源导入落库时亦用同一清单剔除敏感列）
    72→export const SENSITIVE_COLUMN_PATTERN =
    73→  /(password|passwd|pwd|secret|token|api[_-]?key|private[_-]?key|access[_-]?key|id[_-]?card|idcard|身份证|密码|密钥|令牌)/i;
    74→
    75→/** P0-2：与 schemaGuidance 的同名本地定义收敛为共享规范类型 */
    76→type TableLike = SchemaTable;
    77→
    78→/**
    79→ * L3 上下文层敏感过滤：在 scope 白名单过滤之后执行，
    80→ * 把疑似敏感列从进入 LLM 的 Schema 中剔除，返回剔除清单供 UI 标记与审计。
    81→ */
    82→export function filterSensitiveColumns<T extends TableLike>(schema: T[]): {
    83→  schema: T[];
    84→  removed: string[];
    85→} {
    86→  const removed: string[] = [];
    87→  const filtered = (Array.isArray(schema) ? schema : []).map((table) => {
    88→    const columns = Array.isArray(table.columns) ? table.columns : [];
    89→    const kept = columns.filter((c) => {
    90→      const text = `${c?.name || ''} ${c?.description || ''}`;
    91→      if (SENSITIVE_COLUMN_PATTERN.test(text)) {
    92→        removed.push(`${table.name}.${c?.name || ''}`);
    93→        return false;
    94→      }
    95→      return true;
    96→    });
    97→    return { ...table, columns: kept };
    98→  });
    99→  return { schema: filtered, removed };
   100→}
