    56→  if (Array.isArray(out.kpiList)) {
    57→    out.kpiList = out.kpiList.map((k) => fixObjKeys(k, ['label', 'value', 'change']));
    58→  }
    59→  if (Array.isArray(out.charts)) {
    60→    out.charts = out.charts.map((c) => fixObjKeys(c, ['title', 'commentary']));
    61→  }
    62→  return out as T;
    63→}
