   110→/** M4 报告计划批准：计划存储（10 分钟 TTL，一次性消费），机制与 queryPlan 一致；
   111→ * P0-2：配置 REDIS_URL 后外置 Redis（rqp: 键 + GETDEL 原子消费） */
   112→const REPORT_PLAN_TTL_MS = 10 * 60 * 1000;
   113→type ReportPlanEntry = {
   114→  plan: { reportTitle: string; plans: ReportQueryPlan[] };
   115→  templateType: string;
   116→  userId: number;
   117→  dataSourceId: string;
   118→  /** v0.5.2 计划生成时的金额单位口径：批准执行时必须一致，防口径互串 */
   119→  amountUnit?: string;
   120→  expiresAt: number;
   121→};
   122→const reportPlanStore = new Map<string, ReportPlanEntry>();
