   128→export async function storeReportPlan(
   129→  plan: { reportTitle: string; plans: ReportQueryPlan[] },
   130→  meta: { templateType: string; userId: number; dataSourceId: string; amountUnit?: string },
   131→  now = Date.now()
   132→): Promise<string> {
   133→  const id = newReportPlanId();
   134→  if (isRedisEnabled()) {
   135→    const entry: ReportPlanEntry = { plan, ...meta, expiresAt: now + REPORT_PLAN_TTL_MS };
   136→    await getStateStore().setEx(`rqp:${id}`, JSON.stringify(entry), Math.ceil(REPORT_PLAN_TTL_MS / 1000) + 10);
   137→    return id;
   138→  }
   139→  reportPlanStore.set(id, { plan, ...meta, expiresAt: now + REPORT_PLAN_TTL_MS });
   140→  return id;
   141→}
