   143→export type ReportPlanConsumeResult =
   144→  | { ok: true; plan: { reportTitle: string; plans: ReportQueryPlan[] } }
   145→  | { ok: false; reason: string };
   146→
   147→export async function consumeReportPlan(
   148→  planId: string,
   149→  userId: number,
   150→  dataSourceId: string,
   151→  templateType: string,
   152→  amountUnit?: string,
   153→  now = Date.now()
   154→): Promise<ReportPlanConsumeResult> {
   155→  if (isRedisEnabled()) {
   156→    const raw = await getStateStore().getDel(`rqp:${planId}`); // 原子一次性消费防重放
   157→    if (!raw) return { ok: false, reason: '报告计划不存在或已使用，请重新制定' };
   158→    let entry: ReportPlanEntry;
   159→    try {
   160→      entry = JSON.parse(raw);
   161→    } catch {
   162→      return { ok: false, reason: '报告计划不存在或已使用，请重新制定' };
   163→    }
   164→    if (entry.expiresAt <= now) return { ok: false, reason: '报告计划已过期，请重新制定' };
   165→    if (entry.userId !== userId) return { ok: false, reason: '无权使用他人的报告计划' };
   166→    if (entry.dataSourceId !== dataSourceId || entry.templateType !== templateType) {
   167→      return { ok: false, reason: '报告计划与当前数据源/模板不匹配，请重新制定' };
   168→    }
   169→    // v0.5.2 金额单位口径一致性：计划 SQL 已按生成时单位换算，批准时换单位须重新制定
   170→    if ((entry.amountUnit || '') !== (amountUnit || '')) {
   171→      return { ok: false, reason: '金额单位与计划制定时不一致，请重新制定' };
   172→    }
   173→    return { ok: true, plan: entry.plan };
   174→  }
   175→  const entry = reportPlanStore.get(planId);
   176→  if (!entry) return { ok: false, reason: '报告计划不存在或已使用，请重新制定' };
   177→  reportPlanStore.delete(planId); // 一次性消费防重放（无论后续校验是否通过）
   178→  if (entry.expiresAt <= now) return { ok: false, reason: '报告计划已过期，请重新制定' };
   179→  if (entry.userId !== userId) return { ok: false, reason: '无权使用他人的报告计划' };
   180→  if (entry.dataSourceId !== dataSourceId || entry.templateType !== templateType) {
   181→    return { ok: false, reason: '报告计划与当前数据源/模板不匹配，请重新制定' };
   182→  }
   183→  // v0.5.2 金额单位口径一致性：计划 SQL 已按生成时单位换算，批准时换单位须重新制定
   184→  if ((entry.amountUnit || '') !== (amountUnit || '')) {
   185→    return { ok: false, reason: '金额单位与计划制定时不一致，请重新制定' };
   186→  }
   187→  return { ok: true, plan: entry.plan };
   188→}
