   237→/** 阶段一：LLM 生成 2-4 条聚合查询计划（含 1 次校验重试） */
   238→async function generateStage1Plans(
   239→  templateType: string,
   240→  customPrompt: string,
   241→  schema: SchemaTable[],
   242→  guidance: string,
   243→  dsType?: string,
   244→  amountUnit?: string,
   245→  dataSourceId?: string
   246→): Promise<{ reportTitle: string; plans: ReportQueryPlan[] } | null> {
   247→  let parsed: { reportTitle: string; plans: ReportQueryPlan[] } | null = null;
   248→  let lastError = '';
   249→  // v0.5.2 金额单位约定拼在用户消息首位（与问数链路口径一致）
   250→  const unitPrompt = buildAmountUnitPrompt(amountUnit);
   251→  // 语义层指标 + 铁律规则 + 知识库 RAG 并行检索（互不依赖，各自失败降级空串；v0.9.19 起报表与问数同一知识口径；v0.9.35 铁律全量恒注入）
   252→  const [metricPrompt, ironRulesPrompt, knowledgePrompt] = await Promise.all([
   253→    buildReportMetricPrompt(dataSourceId, templateType, customPrompt),
   254→    buildReportIronRulesPrompt(dataSourceId),
   255→    buildReportKnowledgePrompt(dataSourceId, templateType, customPrompt),
   256→  ]);
   257→  for (let attempt = 0; attempt < 2; attempt++) {
   258→    const userPrompt =
   259→      attempt === 0
   260→        ? `${unitPrompt}报表主题：${templateType}\n额外要求：${customPrompt}`
   261→        : `${unitPrompt}报表主题：${templateType}\n额外要求：${customPrompt}\n\n（上次输出未通过校验：${lastError}，请修正后按同一 JSON 契约重新输出。）`;
   262→    let text: string;
   263→    try {
   264→      text = await callLLMJson(buildReportStage1System(schema, guidance, dsType, metricPrompt, ironRulesPrompt, knowledgePrompt), userPrompt);
   265→    } catch {
   266→      return null;
   267→    }
   268→    parsed = parseReportPlans(text);
   269→    if (parsed) break;
   270→    lastError = 'LLM 输出未通过查询计划契约校验';
   271→  }
   272→  return parsed;
   273→}
