   275→function buildReportStage1System(schema: SchemaTable[], guidance: string, dsType?: string, metricPrompt = '', ironRulesPrompt = '', knowledgePrompt = ''): string {
   276→  const dialect = dialectPromptOf(dsType);
   277→  return `你是企业级 NL2SQL 引擎，为高管报表规划真实数据查询。根据报表主题与数据库 Schema，生成 2-4 条 ${dialect.label} SELECT 聚合查询。你不生成任何数据，只生成 SQL。
   278→
   279→数据库 Schema（已经过权限与敏感字段过滤，只能使用其中的表与列；格式：表 {"name","displayName"?,"description"?,"columns":[[列名,类型,中文说明?],…]}）:
   280→${serializeSchemaForPrompt(schema)}
   281→
   282→${extractBusinessNotes(schema)}${guidance ? `可用维度与指标摘要:\n${guidance}\n` : ''}
   283→${metricPrompt}${ironRulesPrompt}${knowledgePrompt}【强制约束】
   284→- 仅输出 JSON 对象: {"reportTitle":"报表标题","queries":[{"title","sql","chartType","xAxisKey","yAxisKeys","columnNames","purpose"}]}
   285→- columnNames: 该查询 SQL 输出每一列的中文表头映射 {"列名/别名": "中文名"}，维度列与聚合别名都要覆盖
   286→- 每条 sql 为单条 SELECT；表名逐字取自 Schema 表 name，列名逐字取自 columns 数组第 1 项，严禁添加 tbl_/t_ 等前缀、后缀或编造不存在的表/列；指标用聚合函数并用 AS 起英文/拼音别名
   287→${dialect.rules}- queries 之间应选择不同维度（如时间趋势、类别对比、结构占比），避免重复
   288→- chartType 从 bar/line/area/pie/donut/radar/treemap/heatmap 选择（时间趋势用 line/area，类别对比用 bar，占比结构用 pie/donut，层级占比用 treemap，多指标横向对照用 heatmap）；xAxisKey 与 yAxisKeys 必须与 SQL 输出列严格一致
   289→- purpose: 一句话说明该图回答的业务问题
   290→- 结果行数控制在 50 行以内（通过聚合或 LIMIT）
   291→- 【文案中文化】reportTitle/title/purpose 中严禁出现英文表名/列名（如 dn_tzsy、BNTFJE），必须使用 Schema 中 displayName/description 对应的中文业务名称
   292→
   293→请只输出纯 JSON，不要包含 markdown 代码块标记或其他说明文字。`;
   294→}
   295→
   296→function parseReportPlans(text: string): { reportTitle: string; plans: ReportQueryPlan[] } | null {
   297→  const parsed = safeParseJson(text);
   298→  if (!parsed) return null;
   299→  const queries = Array.isArray(parsed.queries) ? parsed.queries : Array.isArray(parsed.sqls) ? parsed.sqls : null;
   300→  if (!queries) return null;
   301→  const plans: ReportQueryPlan[] = [];
   302→  for (const q of queries) {
   303→    if (!q || typeof q.sql !== 'string' || !q.sql.trim()) continue;
   304→    plans.push({
   305→      title: typeof q.title === 'string' && q.title.trim() ? q.title : '数据图表',
   306→      sql: q.sql,
   307→      chartType: ['bar', 'line', 'area', 'pie', 'donut', 'radar', 'treemap', 'heatmap'].includes(q.chartType) ? q.chartType : 'bar',
   308→      xAxisKey: typeof q.xAxisKey === 'string' ? q.xAxisKey : '',
   309→      yAxisKeys: Array.isArray(q.yAxisKeys) ? q.yAxisKeys.filter((k: unknown): k is string => typeof k === 'string') : [],
   310→      columnNames: q.columnNames && typeof q.columnNames === 'object' ? q.columnNames : undefined,
   311→      purpose: typeof q.purpose === 'string' ? q.purpose : '',
   312→    });
   313→    if (plans.length >= MAX_REPORT_QUERIES) break;
   314→  }
   315→  if (plans.length === 0) return null;
   316→  return {
   317→    reportTitle: typeof parsed.reportTitle === 'string' && parsed.reportTitle.trim() ? parsed.reportTitle : '',
   318→    plans,
   319→  };
   320→}
