   322→export function buildReportStage2System(schema: SchemaTable[], amountUnit?: string): string {
   323→  const nameMap = buildIdentifierNameMap(schema);
   324→  const nameMapText = Object.entries(nameMap)
   325→    .map(([en, cn]) => `${en} = ${cn}`)
   326→    .join('；');
   327→  // v0.9.41 金额单位口径注入（与问数阶段二同一规则）：防 LLM 按数字规模自行换算表述
   328→  const unitRule = amountUnit
   329→    ? `\n- 【金额单位口径】所有图表的金额数值均已按「${amountUnit}」口径输出（SQL 已完成换算）：summary/insights/kpiList/commentaries 中引用金额必须逐字沿用「${amountUnit}」表述，禁止任何换算或进位改写（包括但不限于 万/百万/万亿/元，如 54505.36亿元 不得写作 5.45万亿元）`
   330→    : '';
   331→  return `你是资深数据分析总监。你将收到一组真实数据库查询结果（各图表的 SQL、行数、列统计与数据样本）。基于这些真实数据撰写高管报表内容。
   332→
   333→【强制约束】
   334→- 仅输出 JSON 对象: {"title","summary","insights","kpiList","commentaries"}
   335→- 所有数值必须来自给定的真实数据与列统计，严禁编造${unitRule}
   336→- title: 报表标题；summary: 200 字以内高管摘要，概括真实数据反映的经营事实
   337→- insights: 4 条战略洞察 [{"title","type","content","actionItem"}]，type 从 positive/warning/info/critical 选择，content 须引用真实数值
   338→- kpiList: 4 个核心 KPI [{"label","value","change","status"}]，value 必须由真实数据计算（可引用列统计），change 仅在数据支持时给出，status 从 good/bad/neutral 选择
   339→- commentaries: 字符串数组，按给定图表顺序逐图解读（每张图 60 字以内，须引用该图真实数据）
   340→- 【文案中文化】title/summary/insights/kpiList/commentaries 中严禁出现英文表名/列名标识符（SQL 中的标识符仅用于理解数据结构，不得出现在文案中），一律使用下列中文业务名称：${nameMapText || '（以 Schema 中文名为准）'}
   341→
   342→请只输出纯 JSON，不要包含 markdown 代码块标记或其他说明文字。`;
   343→}
   344→
   345→/**
   346→ * 执行一次报表生成：阶段一生成查询计划（或复用已批准计划）→ 并行安全执行 → 阶段二生成文案。
   347→ * @param input 报表入参（模板/自定义要求/Schema/数据源/权限等，字段含义见 LiveReportInput）
   348→ * @returns 成功或失败二分支结果（executedSqls 与报告 charts 索引对齐，供图表下钻使用）
   349→ */
   350→export async function runLiveReport(input: LiveReportInput): Promise<LiveReportOutcome> {
   351→  const { templateType, customPrompt, schema, guidance, dataSourceId, dsType, sensitiveRemoved, rowFilters, amountUnit } = input;
   352→  const executedSqls: string[] = [];
   353→
   354→  // 阶段一：生成查询计划（已批准计划直接复用，跳过重新生成）
   355→  let parsed: { reportTitle: string; plans: ReportQueryPlan[] } | null = input.approvedPlans ?? null;
   356→  if (!parsed) {
   357→    parsed = await generateStage1Plans(templateType, customPrompt, schema, guidance, dsType, amountUnit, dataSourceId);
   358→  }
   359→  if (!parsed) {
   360→    return { ok: false, error: '查询计划生成失败', executedSqls };
   361→  }
   362→
   363→  // 执行：多条查询计划并行过安全执行层（v0.9.20，对照问数链路并行化）——
   364→  // 各查询互不依赖，墙钟由「逐条相加」降为「最慢一条」；连接池按场景分级配额排队兜底（chain 默认 5/export 默认 2），
   365→  // 允许部分失败（至少 1 条成功才继续）；汇总仍按计划原顺序（executedSqls 与 charts 索引对齐，图表下钻依赖该顺序）
   366→  const execResults = await Promise.all(
   367→    parsed.plans.map(async (plan) => {
   368→      const outcome = await executeSafeSql(dataSourceId, plan.sql, schema, sensitiveRemoved, 500, rowFilters || {}, input.scenario ?? 'chain');
   369→      if (outcome.ok !== true) {
   370→        logger.warn(`[LiveReport] 查询失败已跳过: ${outcome.reason} | sql: ${plan.sql.slice(0, 200)}`);
   371→        return null;
   372→      }
   373→      return { plan, result: outcome.result };
   374→    })
   375→  );
   376→
   377→  const charts: Record<string, any>[] = [];
   378→  const chartDigests: string[] = [];
   379→  let totalRows = 0;
   380→  for (const item of execResults) {
