    28→      const d = new Date(now.getFullYear(), now.getMonth() - (5 - i), 1);
    29→      return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
    30→    });
    31→  } else {
    32→    const enums = extractEnumValues(dimension.description);
    33→    dimValues = enums.length >= 3 ? enums : Array.from({ length: 5 }, (_, i) => `${dimName}_${i + 1}`);
    34→  }
    35→
    36→  // 确定性伪随机数值（基于列名 hash，保证多次调用结果一致）
    37→  const hashNum = (s: string) => [...s].reduce((a, c) => (a * 31 + c.charCodeAt(0)) % 9973, 7);
    38→  const data = dimValues.map((v, i) => {
    39→    const row: Record<string, any> = { [dimName]: v };
    40→    for (const m of metricNames) {
    41→      row[m] = 800 + ((hashNum(m) * (i + 3) * (i + 1)) % 4200);
    42→    }
    43→    return row;
    44→  });
    45→
    46→  const mainMetric = metrics[0];
    47→  const secondMetric = metrics[1];
    48→  const aggCols = metricNames.map((m) => `SUM(${m}) AS ${m}`).join(', ');
    49→  const tableLabel = table.displayName || table.name;
    50→
    51→  const kpiMetrics = metrics.slice(0, 3).map((m, i) => ({
    52→    label: `总${metricLabel(m)}`,
    53→    value: data.reduce((acc, r) => acc + r[m.name], 0).toLocaleString('zh-CN'),
    54→    change: [12.4, -3.8, 6.1][i] ?? 5.0,
    55→    trend: (i === 1 ? 'down' : 'up') as 'up' | 'down',
    56→    subtext: `基于 ${tableLabel} 的演示统计`,
    57→  }));
    58→
    59→  return {
    60→    generatedSQL: `SELECT ${dimName}, ${aggCols} FROM ${table.name} GROUP BY ${dimName} ORDER BY ${dimName} ASC;`,
    61→    thoughtProcess: [
    62→      `意图识别：围绕「${tableLabel}」分析用户问题`,
    63→      `维度选择：按 ${dimName}（${dimension.description || '维度列'}）分组`,
    64→      `指标计算：${metricNames.map((m) => `SUM(${m})`).join('、')}`,
