    66→    aiExplanation: `（离线演示数据）按 ${dimName} 维度对 ${tableLabel} 的 ${metricLabel(mainMetric)} 进行了聚合分析，${dimValues[dimValues.length - 1]} 的指标表现处于样本区间高位。接入 AI 引擎后将基于真实数据给出精确结论。`,
    67→    keyInsights: [
    68→      `${dimValues[dimValues.length - 1]} 的 ${metricLabel(mainMetric)} 为样本中最高值。`,
    69→      `${metricLabel(mainMetric)} 在各 ${dimName} 间波动明显，建议结合业务背景进一步下钻。`,
    70→      secondMetric ? `${metricLabel(secondMetric)} 与 ${metricLabel(mainMetric)} 走势基本一致，两者可能存在联动。` : `建议补充更多指标列以获得更全面的视角。`,
    71→    ],
    72→    chartConfig: {
